const webhook = $('Webhook').first().json.body;

function extractClamStatus(value) {
  if (value && typeof value === 'object') {
    if (value.Status) {
      return { Status: value.Status, Description: value.Description || '' };
    }
    if (value.error && typeof value.error === 'object') {
      if (value.error.response && value.error.response.body) {
        const inner = extractClamStatus(value.error.response.body);
        if (inner) return inner;
      }
      if (value.error.description) {
        const inner = extractClamStatus(value.error.description);
        if (inner) return inner;
      }
      if (value.error.message) {
        const inner = extractClamStatus(value.error.message);
        if (inner) return inner;
      }
    }
  }
  let text = '';
  try { text = typeof value === 'string' ? value : JSON.stringify(value); } catch (e) { text = String(value); }
  text = text.replace(/\\"/g, '"');
  const m = text.match(/\{"Status":"(OK|FOUND|ERROR)"\s*(?:,"Description":"([^"]*)")?\s*\}/);
  if (m) return { Status: m[1], Description: (m[2] || '').trim() };
  return null;
}

let parsed = extractClamStatus($json);
if (!parsed) {
  parsed = { Status: 'ERROR', Description: 'Unparseable ClamAV response: ' + String($json && $json.message || JSON.stringify($json)).slice(0, 300) };
}

const scanStatus = parsed.Status === 'FOUND' ? 'infected' : (parsed.Status === 'OK' ? 'clean' : 'failed');

return {
  evidence_file_id: webhook.evidence_file_id,
  scan_status: scanStatus,
  virus_name: parsed.Description,
  scan_details: { Status: parsed.Status, Description: parsed.Description }
};

// Read all data from Webhook JSON fields.
// Laravel sends file_base64 and mime_type as plain text form fields,
// so we never need to touch n8n binary data (which is inaccessible in the Code node sandbox).
const webhook = $('Webhook').first().json.body;

return {
  base64: webhook.file_base64,
  mimeType: webhook.mime_type || 'application/octet-stream',
  requirement_text: webhook.requirement_text || '',
  evidence_file_id: webhook.evidence_file_id || '',
  project_name: webhook.project_name || '',
  requirement_num: webhook.requirement_num || '',
  original_filename: webhook.original_filename || '',
  auditor_email: webhook.auditor_email || '',
  review_link: webhook.review_link || '',
  gemini_api_key: webhook.gemini_api_key || ''
};

// Parse Ollama response format
// Ollama returns: {"model":"qwen3.5:4b","response":"...JSON...","done":true}
// Gemini returned: {"candidates":[{"content":{"parts":[{"text":"..."}]}}]}
// qwen vision models sometimes double-encode the JSON (\" and \n escape sequences),
// so we unescape and retry before giving up.

function tryParse(text) {
  try {
    return { ok: true, result: JSON.parse(text) };
  } catch (e) {
    return { ok: false, error: e.message };
  }
}

if ($json.error) {
  return {
    status: 'failed',
    observations: 'Ollama API Error: ' + ($json.error.message || JSON.stringify($json.error)),
    recommendations: 'Please check Ollama connection and settings.',
    gaps: [],
    report_fields: {}
  };
}

let responseText = '';
if ($json.response) {
  // Ollama format
  responseText = $json.response;
} else if ($json.candidates && $json.candidates[0]) {
  // Gemini fallback format
  responseText = $json.candidates[0].content.parts[0].text;
}

if (!responseText) {
  return {
    status: 'failed',
    observations: 'AI Analysis Failed: No response from AI.',
    recommendations: 'Verify the Ollama service is running and the model is loaded.',
    gaps: [],
    report_fields: {}
  };
}

responseText = responseText.replace(/```json/g, '').replace(/```/g, '').trim();

let parsed = tryParse(responseText);
if (!parsed.ok) {
  // qwen3.5 double-escapes quotes and newlines; unescape and retry
  const cleaned = responseText
    .replace(/\\"/g, '"')
    .replace(/\\n/g, '\n')
    .replace(/\\t/g, '\t');
  parsed = tryParse(cleaned);
}
if (!parsed.ok) {
  // Raw newlines inside string values violate strict JSON; collapse them and retry
  parsed = tryParse(responseText.replace(/\r?\n/g, ' '));
}

let result = null;
if (parsed.ok) {
  result = parsed.result;
  // If a double-decode left us with a JSON string, parse that inner value too
  if (typeof result === 'string') {
    const inner = tryParse(result);
    if (inner.ok) {
      result = inner.result;
    }
  }
} else {
  // Regex fallback: extract status / observations / recommendations fields
  const s = responseText;
  const st = s.match(/"status"\s*:\s*"([^"]*)"/);
  const ob = s.match(/"observations"\s*:\s*"([\s\S]*?)"(?=\s*,)/);
  const rc = s.match(/"recommendations"\s*:\s*"([\s\S]*?)"(?=\s*[,}])/);
  result = {
    status: st ? st[1] : 'completed',
    observations: ob ? ob[1] : 'No observations generated by AI.',
    recommendations: rc ? rc[1] : 'None'
  };
}

let observations = result.observations || 'No observations generated by AI.';
if (Array.isArray(observations)) {
  observations = observations.join('\n');
} else if (typeof observations !== 'string') {
  observations = JSON.stringify(observations);
}

let recommendations = result.recommendations || 'None';
if (Array.isArray(recommendations)) {
  recommendations = recommendations.join('\n');
} else if (typeof recommendations !== 'string') {
  recommendations = JSON.stringify(recommendations);
}

const gaps = Array.isArray(result.gaps) ? result.gaps : [];

// Structured draft fields for the Gap Assessment review form. The auditor reviews
// and edits every one of these in the Evidence Hub before anything is pushed to
// the Gap Assessment -- the AI's output here is a starting draft, not a verdict.
const reportFields = {
  is_compliant: typeof result.is_compliant === 'boolean' ? result.is_compliant : null,
  risk_rating: result.risk_rating || null,
  gap_description: result.gap_description || null,
  impact_assessment: result.impact_assessment || null,
  gap_category: result.gap_category || null,
  non_compliant_details: result.non_compliant_details || null,
  compliant_description: result.compliant_description || null,
  remediation_plan: result.remediation_plan || null,
  test_results: result.test_results || null,
  meets_standard: typeof result.meets_standard === 'boolean' ? result.meets_standard : null
};

return {
  status: result.status === 'completed' ? 'completed' : 'failed',
  observations: observations,
  recommendations: recommendations,
  gaps: gaps,
  report_fields: reportFields
};
